from itertools import permutations

people = ['Blake', 'Casey', 'Emery', 'Jordan']
colors = ['green', 'orange', 'red', 'yellow']
pets = ['bird', 'dog', 'fish', 'horse']
drinks = ['juice', 'milk', 'tea', 'water']

def find_house(houses, key, value):
    for h in houses:
        if h[key] == value:
            return h
    return None

def check_constraints(houses):
    blake = find_house(houses, 'person', 'Blake')
    jordan = find_house(houses, 'person', 'Jordan')
    casey = find_house(houses, 'person', 'Casey')
    fish = find_house(houses, 'pet', 'fish')
    orange = find_house(houses, 'color', 'orange')
    juice = find_house(houses, 'drink', 'juice')
    yellow = find_house(houses, 'color', 'yellow')
    milk = find_house(houses, 'drink', 'milk')
    red = find_house(houses, 'color', 'red')

    # Clue 1: Fish owner immediately left of Blake
    if fish['pos'] != blake['pos'] - 1:
        return False

    # Clue 2: Bird owner is Jordan
    if jordan['pet'] != 'bird':
        return False

    # Clue 3: Green house is Blake
    if blake['color'] != 'green':
        return False

    # Clue 4: Juice drinker next to orange house
    if abs(juice['pos'] - orange['pos']) != 1:
        return False

    # Clue 5: Casey owns horse
    if casey['pet'] != 'horse':
        return False

    # Clue 6: Jordan next to orange house
    if abs(jordan['pos'] - orange['pos']) != 1:
        return False

    # Clue 7: Orange house drinks water
    if orange['drink'] != 'water':
        return False

    # Clue 8: Yellow house immediately left of milk drinker
    if milk['pos'] != yellow['pos'] + 1:
        return False

    # Clue 9: Red house immediately left of Blake
    if red['pos'] != blake['pos'] - 1:
        return False

    return True

for perm_people in permutations(people):
    for perm_colors in permutations(colors):
        for perm_pets in permutations(pets):
            for perm_drinks in permutations(drinks):
                houses = []
                for i in range(4):
                    houses.append({
                        'pos': i + 1,
                        'person': perm_people[i],
                        'color': perm_colors[i],
                        'pet': perm_pets[i],
                        'drink': perm_drinks[i]
                    })

                if check_constraints(houses):
                    yellow_person = find_house(houses, 'color', 'yellow')['person']
                    print(f"ANSWER: {yellow_person}")
                    exit()
